const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCTS = [
  '==', '!=', '<=', '>=', '&&', '||', '->', '=>',
  '+', '-', '*', '/', '%', '=', '<', '>', '!',
  '(', ')', '{', '}', '[', ']', ',', ';', '.',
]

function isLetter(ch) {
  return ch !== undefined && /[A-Za-z]/.test(ch)
}
function isDigit(ch) {
  return ch !== undefined && /[0-9]/.test(ch)
}
function isIdentCont(ch) {
  return ch !== undefined && /[A-Za-z0-9_]/.test(ch)
}

export function scan(src) {
  const s = src
  const len = s.length
  let i = 0
  let line = 1
  let col = 1
  const tokens = []

  function peekCP() {
    if (i >= len) return -1
    return s.codePointAt(i)
  }

  function cpLen(cp) {
    return cp > 0xffff ? 2 : 1
  }

  function advance() {
    const cp = s.codePointAt(i)
    const l = cpLen(cp)
    if (cp === 0x0a) {
      line++
      col = 1
    } else if (cp === 0x09) {
      col = Math.floor((col - 1) / 4) * 4 + 5
    } else {
      col++
    }
    i += l
    return cp
  }

  function scanString(startLine, startCol) {
    advance() // opening quote
    let result = ''
    while (true) {
      if (i >= len) throw new ScanError(startLine, startCol, 'unterminated string')
      const cp = peekCP()
      if (cp === 0x22) {
        advance()
        break
      }
      if (cp === 0x0a) {
        throw new ScanError(line, col, 'newline in string')
      }
      if (cp === 0x5c) {
        const bsLine = line
        const bsCol = col
        advance() // backslash
        if (i >= len) throw new ScanError(startLine, startCol, 'unterminated string')
        const ecp = peekCP()
        if (ecp === 0x0a) {
          throw new ScanError(line, col, 'newline in string')
        }
        const ech = String.fromCodePoint(ecp)
        if (ech === 'n') {
          result += '\n'
          advance()
        } else if (ech === 't') {
          result += '\t'
          advance()
        } else if (ech === 'r') {
          result += '\r'
          advance()
        } else if (ech === '\\') {
          result += '\\'
          advance()
        } else if (ech === '"') {
          result += '"'
          advance()
        } else if (ech === '0') {
          result += '\0'
          advance()
        } else if (ech === 'x') {
          advance() // x
          const h1 = i < len ? s[i] : null
          const h2 = i + 1 < len ? s[i + 1] : null
          if (h1 === null || h2 === null) {
            throw new ScanError(startLine, startCol, 'unterminated string')
          }
          if (/[0-9a-fA-F]/.test(h1) && /[0-9a-fA-F]/.test(h2)) {
            result += String.fromCharCode(parseInt(h1 + h2, 16))
            advance()
            advance()
          } else {
            throw new ScanError(bsLine, bsCol, 'invalid escape \\x')
          }
        } else if (ech === 'u') {
          advance() // u
          if (i >= len) throw new ScanError(startLine, startCol, 'unterminated string')
          if (s[i] !== '{') {
            throw new ScanError(bsLine, bsCol, 'invalid escape \\u')
          }
          advance() // {
          let hex = ''
          while (i < len && /[0-9a-fA-F]/.test(s[i])) {
            hex += s[i]
            advance()
          }
          if (i >= len) throw new ScanError(startLine, startCol, 'unterminated string')
          if (hex.length === 0 || s[i] !== '}') {
            throw new ScanError(bsLine, bsCol, 'invalid escape \\u')
          }
          const val = parseInt(hex, 16)
          if (val > 0x10ffff) {
            throw new ScanError(bsLine, bsCol, 'invalid escape \\u')
          }
          advance() // }
          result += String.fromCodePoint(val)
        } else {
          throw new ScanError(bsLine, bsCol, `invalid escape \\${ech}`)
        }
      } else {
        result += String.fromCodePoint(cp)
        advance()
      }
    }
    return { line: startLine, col: startCol, kind: 'string', text: JSON.stringify(result) }
  }

  function scanRawString(startLine, startCol) {
    advance() // 'r'
    advance() // opening quote
    let result = ''
    while (true) {
      if (i >= len) throw new ScanError(startLine, startCol, 'unterminated string')
      const cp = peekCP()
      if (cp === 0x22) {
        advance()
        break
      }
      result += String.fromCodePoint(cp)
      advance()
    }
    return { line: startLine, col: startCol, kind: 'rawstring', text: JSON.stringify(result) }
  }

  function scanNumber(startLine, startCol) {
    const startIdx = i

    function consumeDigitRun(test) {
      let count = 0
      while (i < len) {
        if (test(s[i])) {
          advance()
          count++
          continue
        }
        if (s[i] === '_' && count > 0 && i + 1 < len && test(s[i + 1])) {
          advance()
          continue
        }
        break
      }
      return count
    }

