      advance()
      advance()
      const c = consumeDigitRun((ch) => /[01]/.test(ch))
      if (c === 0) prefixNoDigit = true
    } else if (s[i] === '0' && (s[i + 1] === 'o' || s[i + 1] === 'O')) {
