      if (s[i] === '.' && i + 1 < len && /[0-9]/.test(s[i + 1])) {
        advance() // .
        consumeDigitRun((ch) => /[0-9]/.test(ch))
      }
      if (s[i] === 'e' || s[i] === 'E') {
        let j = i + 1
        let sign = false
        if (s[j] === '+' || s[j] === '-') {
          sign = true
          j++
        }
        if (j < len && /[0-9]/.test(s[j])) {
          advance() // e/E
          if (sign) advance() // sign
          consumeDigitRun((ch) => /[0-9]/.test(ch))
        }
      }
    }

    let invalid = prefixNoDigit
    if (i < len && isIdentCont(s[i])) invalid = true

    if (invalid) {
      while (i < len && isIdentCont(s[i])) advance()
      const text = s.slice(startIdx, i)
      throw new ScanError(startLine, startCol, `invalid number ${text}`)
    }

    const text = s.slice(startIdx, i)
    return { line: startLine, col: startCol, kind: 'number', text }
  }

  while (i < len) {
    const startLine = line
    const startCol = col
    const cp = peekCP()

    if (cp === 0x20 || cp === 0x09 || cp === 0x0d || cp === 0x0a) {
      advance()
      continue
    }

    const ch = String.fromCodePoint(cp)

    if (ch === '/' && s[i + 1] === '/') {
      advance()
      advance()
      while (i < len && peekCP() !== 0x0a) advance()
      continue
    }

    if (ch === '/' && s[i + 1] === '*') {
      const openLine = startLine
      const openCol = startCol
      advance()
      advance()
      let depth = 1
      while (depth > 0) {
        if (i >= len) throw new ScanError(openLine, openCol, 'unterminated block comment')
        if (s[i] === '/' && s[i + 1] === '*') {
          advance()
          advance()
          depth++
          continue
        }
        if (s[i] === '*' && s[i + 1] === '/') {
          advance()
          advance()
          depth--
          continue
        }
        advance()
      }
      continue
    }

    if (ch === '"') {
      tokens.push(scanString(startLine, startCol))
      continue
    }

    if (ch === 'r' && s[i + 1] === '"') {
      tokens.push(scanRawString(startLine, startCol))
      continue
    }

    if (isLetter(ch) || ch === '_') {
      const start = i
      advance()
      while (i < len && isIdentCont(s[i])) advance()
      const text = s.slice(start, i)
      const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
      tokens.push({ line: startLine, col: startCol, kind, text })
      continue
    }

    if (isDigit(ch)) {
      tokens.push(scanNumber(startLine, startCol))
      continue
    }

    let matched = null
    for (const p of PUNCTS) {
      if (s.startsWith(p, i)) {
        matched = p
        break
      }
    }
    if (matched) {
      for (let k = 0; k < matched.length; k++) advance()
      tokens.push({ line: startLine, col: startCol, kind: 'punct', text: matched })
      continue
    }

    throw new ScanError(startLine, startCol, `unexpected character ${ch}`)
  }

  return tokens
}
