/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */
import { readFileSync } from 'node:fs'
import { scan, ScanError } from './lexer.js'

const mode = process.argv[2]

if (mode !== 'tokens' && mode !== 'stats') {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}

let input = ''
try {
  input = readFileSync(0, 'utf8')
} catch {
  input = ''
}

try {
  const tokens = scan(input)

  if (mode === 'tokens') {
    let out = ''
    for (const t of tokens) {
      out += `${t.line}:${t.col} ${t.kind} ${t.text}\n`
    }
    process.stdout.write(out)
  } else {
    const counts = { ident: 0, keyword: 0, number: 0, punct: 0, rawstring: 0, string: 0 }
    for (const t of tokens) counts[t.kind]++
    const order = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']
    let out = ''
    let total = 0
    for (const k of order) {
      out += `${k} ${counts[k]}\n`
      total += counts[k]
    }
    out += `total ${total}\n`
    process.stdout.write(out)
  }
  process.exit(0)
} catch (e) {
  if (e instanceof ScanError) {
    process.stderr.write(`error: ${e.line}:${e.col}: ${e.reason}\n`)
    process.exit(2)
  }
  throw e
}
"}

